  "계정 탈퇴": "Delete account",
  "확인을 위해 \"{0}\" 입력": "To confirm, type \"{0}\"",
  "백의 첫 수. e4는 개방적·공격적, d4는 전략적·폐쇄적": "White's first move. e4 is open and aggressive; d4 is strategic and closed",
  "이탈리안 게임의 갈림길. 흑 …Bc5(지우코 피아노, 조용한 전략전) 또는 …Nf6(투 나이츠, 날카로운 전술전). 채택률 비슷": "The crossroads of the Italian Game. Black plays …Bc5 (Giuoco Piano, a quiet strategic fight) or …Nf6 (Two Knights, a sharp tactical fight). Both are about equally popular",
  "4.Ng5는 f7 직접 위협. 평가를 지키는 수는 사실상 4...d5뿐": "4.Ng5 directly threatens f7. In practice 4...d5 is the only move that holds the evaluation",
  "트랙슬러 카운터어택. f7을 내주고 f2를 맞받는 함정 수": "The Traxler Counterattack. A trappy move that gives up f7 and hits back at f2",
  "백의 첫 수. 게임 전체 성격(개방/폐쇄, 전술/전략)을 정하는 최상위 분기": "White's first move. The top-level branch that sets the character of the whole game (open or closed, tactical or strategic)",
  "흑의 선택지: 1...e5(오픈 게임), c5(시칠리안), e6(프렌치), c6(카로칸)": "Black's options: 1...e5 (Open Game), c5 (Sicilian), e6 (French), c6 (Caro-Kann)",
  "흑 e5 방어: 2...Nc6(정통), Nf6(페트로프), d6(필리도르)": "Black's defense of e5: 2...Nc6 (classical), Nf6 (Petrov), d6 (Philidor)",
  "백의 공격 플랜: 3.Bb5(루이 로페즈, 구조적 압박) vs 3.Bc4(이탈리안, 빠른 f7 공략)": "White's attacking plan: 3.Bb5 (Ruy Lopez, structural pressure) vs 3.Bc4 (Italian, a quick attack on f7)",
  "이탈리안의 성격: 3...Bc5(지우코 피아노, 전략전) vs 3...Nf6(투 나이츠, 전술전)": "Character of the Italian: 3...Bc5 (Giuoco Piano, strategic) vs 3...Nf6 (Two Knights, tactical)",
  "프라이드 리버: f7 위협에 4...d5만 사실상 유일한 정수": "Fried Liver: against the f7 threat, 4...d5 is practically the only good move",
  "루이 로페즈 핵심: 3...a6(모펀 메인) vs 3...Nf6(베를린 디펜스)": "Ruy Lopez key point: 3...a6 (Morphy main line) vs 3...Nf6 (Berlin Defense)",
  "안티-시칠리안: 2.Nf3(오픈 시칠리안) vs 2.Nc3 / c3 / Bc4(폐쇄·알라핀 등)": "Anti-Sicilian: 2.Nf3 (Open Sicilian) vs 2.Nc3 / c3 / Bc4 (closed lines, Alapin, etc.)",
  "오픈 시칠리안: 2...d6(나이도르프/드래곤), Nc6(스벤니/클래식), e6(타이마노프/카안)": "Open Sicilian: 2...d6 (Najdorf/Dragon), Nc6 (Sveshnikov/Classical), e6 (Taimanov/Kan)",
  "프렌치 구조: 3.Nc3, Nd2(타라쉬), e5(어드밴스), exd5(익스체인지)로 폰 구조가 갈림": "French structures: the pawn structure splits after 3.Nc3, Nd2 (Tarrasch), e5 (Advance), exd5 (Exchange)",
  "카로칸 구조: 3.Nc3/Nd2(클래시컬), e5(어드밴스), exd5(익스체인지), f3(핀란드)": "Caro-Kann structures: 3.Nc3/Nd2 (Classical), e5 (Advance), exd5 (Exchange), f3 (Finnish)",
  "흑의 응수: 1...d5(정통 폐쇄) vs 1...Nf6(인디언, 초현대적 중앙 양보)": "Black's reply: 1...d5 (classical, closed) vs 1...Nf6 (Indian, hypermodern: giving up the center)",
  "퀸스 갬빗: 2...e6(QGD), c6(슬라브), dxc4(QGA)": "Queen's Gambit: 2...e6 (QGD), c6 (Slav), dxc4 (QGA)",
  "인디언 디펜스: 2...e6(님조/QID), g6(KID/그륀펠트), c5(베노니)": "Indian Defenses: 2...e6 (Nimzo/QID), g6 (KID/Grünfeld), c5 (Benoni)",
  "3...Bb4(님조-인디언, 핀) vs 3...d5(QGD 전환)": "3...Bb4 (Nimzo-Indian, a pin) vs 3...d5 (transposing to the QGD)",
  "3...d5(그륀펠트, 중앙 반격) vs 3...Bg7→d6(킹스 인디언, 폐쇄 공격)": "3...d5 (Grünfeld, a counterattack in the center) vs 3...Bg7→d6 (King's Indian, closed attack)",
  "다미아노 디펜스 응징의 핵심. 4.Qh5+ 더블 어택으로 e5 폰 회수, 흑 킹 노출": "The key to punishing the Damiano Defense. 4.Qh5+ is a double attack that wins back the e5 pawn and exposes Black's king",
  "폰지아니 오프닝. d4를 준비하며 중앙을 노리는 고전 정석": "The Ponziani Opening. A classic line that prepares d4 and eyes the center",
  "스칸디나비안 디펜스. 흑이 d5로 중앙을 바로 교환해 빠르게 전개. 백은 2.exd5 뒤 퀸/나이트 회수 라인으로 분기": "The Scandinavian Defense. Black challenges the center at once with d5 and develops quickly. After 2.exd5, White branches into lines that recapture with the queen or knight",
  "이미지를 읽지 못함": "Couldn't read the image",
  "네트워크 오류로 이미지 인식 실패": "Image recognition failed due to a network error",
  "기물을 희생하면서도 포지션을 유리하게 이끄는, 찾기 어려운 최상의 수": "A hard-to-find top move that sacrifices material yet steers the position in your favor",
  "두지 않으면 포지션이 크게 나빠지는, 사실상 유일하게 좋은 수": "If you don't play it, the position gets much worse. Practically the only good move",
