  "피크 레이팅": "Peak rating",
  "/user 페이지 우상단 X 버튼을 점 3개 메뉴(신고·차단)로 교체했습니다. 좌상단에 @아이디 표시합니다.": "Replaced the top-right X on the /user page with a three-dot menu (report/block). The @ID now shows at the top left.",
  "신고 사유를 체크박스로 중복 선택했습니다. 개발자 모드에서 신고자·신고 대상 아이디와 신고 내용(최근 대화 포함) 열람 추가했습니다.": "Report reasons can now be multi-selected with checkboxes. In developer mode, view the reporter and reported IDs and the report content (including recent chat).",
  "채팅창 상단에 '최근 활동' 표시합니다. 신고·차단 버튼을 점 3개 메뉴로 통합했습니다.": "Added 'Last active' under the ID at the top of chats. Merged the report and block buttons into a three-dot menu.",
  "채팅의 모든 요소(카드·알림 포함)에 반응 가능 추가했습니다. 더블클릭하면 하트 반응 추가했습니다. 반응 이모지를 말풍선에 붙여 표시합니다.": "React to every chat element, including cards and notices. Double-click to react with a heart. Reaction emojis now sit right against the bubble.",
  "대국 신청 카드의 띄어쓰기 오류를 수정했습니다. '끝난 대국'을 '대국 종료됨'으로 표기합니다.": "Fixed a spacing error on game request cards. 'Finished game' now reads 'Game ended'.",
  "미니게임 육각형 엠블럼에서 'MiniGame' 글자 삭제했습니다.": "Removed the 'MiniGame' text from the mini-game hexagon emblem.",
  "신고 사유 (중복 선택 가능)": "Report reasons (select all that apply)",
  "신고한 메시지와 최근 대화는 검토를 위해 운영진에게 전달. 상대에게는 알리지 않음": "The reported message and recent chat are sent to the team for review. The other user is not notified",
  "신고 목록": "Reports",
  "새로 고침": "Refresh",
  "처리 대기": "Pending",
  "처리 완료": "Resolved",
  "서버에 반영되지 않음. supabase-setup.sql 재실행 필요": "Not applied on the server. Re-run supabase-setup.sql",
  "불러오기 실패": "Failed to load",
  "신고 없음": "No reports",
  "프로필 신고": "Profile report",
  "신고된 메시지": "Reported message",
  "대화 기록": "Chat history",
  "대국 종료됨": "Game ended",
  "대결 종료됨": "Match ended",
  "최근 활동 : {0}": "Last active: {0}",
  "분석 탭 수 블록의 공개 데이터 통계가 '- / -'로 남거나 채택률 막대가 비던 문제를 수정했습니다. 통계 조회가 실패하면 자동으로 다시 시도 추가했습니다.": "Fixed public data stats on analysis move blocks staying as '— / —' or showing an empty adoption bar. Failed stat requests now retry automatically.",
  "프로필의 통계 전환 버튼을 'OpenChess'·'외부 사이트' 글자로 변경했습니다.": "Changed the profile stats switch to text buttons: 'OpenChess' and 'external site'.",
  "미니게임 랭킹 화면의 중복된 '로비' 버튼 삭제했습니다.": "Removed the redundant 'Lobby' button from the mini-game ranking screen.",
  "일반 대국 전적·레이팅·랭킹 추가했습니다. 랜덤 매칭 결과가 미니게임과 같은 형태의 랭킹에 반영했습니다.": "Added record, rating and ranking for standard games. Random-match results now count toward a ranking in the same format as the mini-games.",
  "나이트 레이스 이동 수 제한 삭제했습니다. 제한시간 안이면 몇 수든 이동 가능 추가했습니다.": "Removed the move limit in Knight Race. Make as many moves as you like within the time limit.",
  "나이트 레이스 혼자 플레이에서 목표에 못 닿으면 정산 전에 최단 경로를 금색 화살표로 표시합니다.": "In solo Knight Race, if you fail to reach the target, the shortest path is shown with gold arrows before the round summary.",
  "나이트 레이스 거리 판정 연출이 칸에서 어긋나던 문제를 수정했습니다.": "Fixed the Knight Race distance-tiebreak animation drifting off the squares.",
  "무한 체크메이트 포지션을 수천 개로 확대했습니다. 백랭크·스모더드 등 다양한 체크메이트 모양을 고르게 출제하며, 한 번 나온 포지션은 모두 소진하기 전까지 다시 나오지 않습니다.": "Expanded Endless Checkmate to thousands of positions. A wide variety of checkmate patterns, such as back-rank and smothered mates, come up evenly, and a position never repeats until all of them have been used.",
  "무한 체크메이트 대전에서 상대의 진행 상황(수순 탐색 중·정확한 수순·실패·체크메이트 성공) 표시합니다.": "Endless Checkmate matches now show your opponent's progress: looking for the line, correct line, failed, or checkmate achieved.",
  "무한 체크메이트 동점 시 결과 화면 전에 등급별 성공 수를 하나씩 비교하는 정산 화면 추가했습니다.": "When Endless Checkmate ends in a tie, a tiebreaker screen compares successes grade by grade before the result.",
  "일반 대국 랭킹, 나이트 레이스 개선, 무한 체크메이트 대폭 확장, 공개 데이터 통계 표시 수정했습니다.": "Standard game ranking, Knight Race improvements, Major Endless Checkmate expansion, public data stats fix.",
  "일반 대국 랭킹, 나이트 레이스 최단 경로 화살표, 체크메이트 포지션 수천 개, 상대 진행 상황 표시합니다.": "Standard game ranking, Knight Race shortest-path arrows, Thousands of checkmate positions, Opponent progress display",
  "일반 대국 랭킹, 나이트 레이스 최단 경로 화살표, 체크메이트 포지션 수천 개, 상대 진행 상황 표시": "Standard game ranking, Knight Race shortest-path arrows, Thousands of checkmate positions, Opponent progress display",
