  "보드 스킨·기물 스킨 모음. 기본 스킨은 바로 장착, 상점에서 구매한 스킨도 여기서 장착·구매 가능. 미보유 스킨은 미리보기": "A collection of board and piece skins. Default skins equip instantly; skins bought in the shop can be equipped or bought here too. Skins you don't own are shown as previews",
