  "퍼즐 {0}": "Puzzles {0}",
  "체스컴 {0}": "chess.com {0}",
  "도감 해금률 {0}": "Openings unlocked {0}",
  "퀸으로 승진하면 상대가 둘 수 있는 합법수가 없어져 스테일메이트로 무승부가 되므로, 대신 {0:을/를} 골라 승진하는 수입니다.": "Promoting to a queen would be stalemate, a draw. Promoting to a {0} instead",
  "퀸으로 승진하면 곧바로 잡히지만 {0:은/는} 안전하게 남을 수 있어, 대신 {0:을/를} 골라 승진하는 수입니다.": "A queen promotion would be captured at once. The {0} promotion stays safe",
  "퀸이 아닌 {0:을/를} 골라 승진하는, 흔치 않은 감각의 수입니다.": "Promoting to a {0} instead of a queen. An unusual choice",
  "{0:과/와} {1:을/를} 교환하는 건 쉽지 않은 선택이지만, 지금 상황에선 탁월한 선택입니다.": "Trading {0} for {1}. Not easy, but a brilliant choice in this situation",
  "{0:을/를} 그대로 걸어 둔 채 그 위협을 무시하고, 대신 더 큰 이득을 얻어내는 수입니다.": "A move that ignores the threat to the {0} and wins something bigger",
  "{0:을/를} 내주는 과감한 희생으로, 눈앞의 손해를 감수하고 더 큰 것을 노리는 수입니다.": "A {0} sacrifice. Accepts an immediate loss to go for something bigger",
  "눈에 보이는 손해를 감수하면서까지 더 큰 것을 노리는, 찾기 쉽지 않은 수입니다.": "A move that accepts a visible loss to go for something bigger",
  "이미 불리하던 상황에서 그대로 두면 계속 밀릴 뿐이라, {0} 수순으로 {1:을/를} 만들어 무승부를 강제해야 했던 수입니다.": "Already in a bad position. The line {0} forces a draw by {1}",
