  "이미지 저장": "Save image",
  "백의 첫 수. e4·d4가 압도적. b4(폴란드)·f4(버드)처럼 평가가 떨어지는 수는 부정확으로 분류": "White's first move. e4 and d4 dominate. Moves that lower the evaluation, like b4 (Polish) and f4 (Bird), are classed as inaccuracies",
  "킹 폰 오프닝. 중앙 점유, 비숍·퀸 길을 열어 빠른 전개와 공격": "King's Pawn Opening. Takes the center and opens lines for the bishop and queen for quick development and attack",
  "퀸 폰 오프닝. e4보다 폐쇄적·전략적, 안정적인 중앙 장악": "Queen's Pawn Opening. Closed and more strategic than e4, with a steady grip on the center",
  "이탈리안 게임. 비숍을 c4로 보내 f7 약점 공략. 흑 …Bc5(지우코 피아노) 또는 …Nf6(투 나이츠)": "Italian Game. The bishop goes to c4 to attack the f7 weakness. Black replies …Bc5 (Giuoco Piano) or …Nf6 (Two Knights)",
  "루이 로페즈(스패니시). 흑 c6 나이트를 압박해 e5 폰 수비를 흔듦. 가장 깊이 연구된 오프닝 중 하나": "Ruy Lopez (Spanish). Pressures Black's c6 knight to shake the defense of the e5 pawn. One of the most deeply studied openings",
  "시칠리안 디펜스. 비대칭 구조로 반격. 최상위에서 가장 인기 있는 e4 대응": "Sicilian Defense. Counterattacks with an asymmetrical structure. The most popular reply to e4 at the top level",
  "님조/퀸즈 인디언 계열 입구. 흑이 유연하게 중앙 통제": "The entrance to the Nimzo/Queen's Indian family. Black controls the center flexibly",
  "{0} 정석 이론대로 전개되는 라인": "A line that follows the standard {0} theory",
  "2...f6는 f7-킹 대각선을 약화시키고 나이트 출구를 막는 대표적인 악수. 백은 e5 폰을 희생해 바로 응징 가능": "2...f6 is a classic bad move that weakens the f7–king diagonal and blocks the knight's retreat. White can punish it at once by sacrificing the e5 pawn",
  "3.Nxe5! 나이트를 내주고 폰을 잡으며 f7-h5 대각선 공략": "3.Nxe5! Gives up the knight to take the pawn and attacks along the f7–h5 diagonal",
  "3...fxe5 받으면(거의 강제) e8-h5 대각선이 완전히 열림": "If 3...fxe5 is taken (almost forced), the e8–h5 diagonal opens completely",
  "4.Qh5+ 더블 어택. 4...Ke7 5.Qxe5+로 룩까지 따내며 백 대승": "4.Qh5+ is a double attack. After 4...Ke7 5.Qxe5+ White even wins the rook and scores a big victory",
  "5...Nxd5?는 폰을 되찾지만 f7이 무방비. 백은 나이트를 희생하는 프라이드 리버로 응징": "5...Nxd5? wins the pawn back but leaves f7 undefended. White punishes it with the Fried Liver, sacrificing a knight",
  "6.Nxf7! 나이트를 희생해 킹을 끌어냄": "6.Nxf7! Sacrifices the knight to drag the king out",
  "6...Kxf7 받으면 킹이 노출": "If 6...Kxf7 is taken, the king is exposed",
  "7.Qf3+ 킹과 d5 나이트를 동시에 공격. 백이 주도권": "7.Qf3+ attacks the king and the d5 knight at the same time. White holds the initiative",
  "(시작 위치)": "(starting position)",
