  "불러오기": "Load",
  "PGN은 검증 후 그 수순 그대로 분석 탭에서 이어 둘 수 있음. FEN은 그 포지션(차례·캐슬링 권리·앙파상 포함)부터 이어 두는 FEN 모드로 전환되고, 처음 두는 수가 1수로 표기됨": "A PGN is verified, then you can continue from its moves in the Analysis tab. A FEN switches to FEN mode, continuing from that position (including side to move, castling rights, and en passant), and your first move is numbered 1",
