  "Tip: \"12.Nf3\"처럼 수 번호와 함께 적으면 해당 수로 이동하는 링크가 됨. 이어지는 수순으로 링크하려면 {0}처럼 대괄호 두 개 안에 수 번호와 수순을 공백으로 구분해 적기. 대괄호 안은 150자 제한에서 제외": "Tip: writing a move with its number, like \"12.Nf3\", turns it into a link to that move. To link to a following sequence, put the move number and moves inside double square brackets separated by spaces, like {0}. Text inside the brackets doesn't count toward the 150-character limit",
