  "FIDE 래피드 랭킹": "FIDE Rapid ranking",
  "FIDE 블리츠 랭킹": "FIDE Blitz ranking",
  "대진표": "Bracket",
  "마스터 대국 DB에 이 연도 대국 없음": "No games for this year in the master games DB",
  "앱스토어 출시 준비 추가했습니다. 로그인을 시스템 브라우저로 처리하고 앱 링크로 돌아오도록 연결, 체스 엔진은 필요할 때 내려받도록 변경했습니다.": "App Store release prep: sign-in now goes through the system browser and returns via app links, and the chess engine is downloaded on demand.",
  "모든 수의 등급(탁월·최선·실수 등)을 보드 위 효과로 표시합니다. 설정에서 모두, 탁월/유일만, 끔 중에서 선택했습니다.": "Every move grade (brilliant, best, mistake, etc.) now shows as a board effect. Choose All, Brilliant/Only-move only, or Off in settings.",
  "도감에 '마스터' 탭 추가했습니다. 세계 챔피언 계보와 대회(우승자·마스터 대국 DB 집계·대표 대국), 회로도 모양의 마스터 트리, FIDE 스탠다드·래피드·블리츠 상위 100위 랭킹, 대국 DB 최고 레이팅 상위 900명 마스터 추가했습니다.": "Added a 'Masters' tab to the dex: the world champion lineage, tournaments (winners, master-games DB tally, featured games), a circuit-style masters tree, the FIDE top 100 in Standard, Rapid and Blitz, and the top 900 masters in the games DB by peak rating.",
  "마스터 이름을 한글로 표기하고 국적을 국기 이모지로 표시합니다. 최고 레이팅 알약 왼쪽에 MAX 표시합니다.": "Master names are shown in Korean and nationalities as flag emoji. A MAX label sits left of the peak-rating pill.",
  "'외부로 공유' 화면을 모든 곳에서 같은 모양으로 통일했습니다.": "Unified the 'Share externally' screen so it looks the same everywhere.",
  "플레이 탭의 미니게임 이름·레이팅 배치를 정리하고, 일반 대국 카드에 레이팅 줄(배치를 마친 분류만)과 타임 컨트롤 분류별 레이팅 알약 추가했습니다. 상단의 '내 기록·래피드' 제목 삭제했습니다.": "Tidied the mini-game name and rating layout in the Play tab, and added a rating row (only for placed categories) and per-time-control rating chips to the standard game card. Removed the 'My record, Rapid' title at the top.",
  "오프닝 트리의 보이는 영역과 드래그 감도를 마스터 트리와 같게 통일하고, 마스터 트리에 확대·축소(100% 기준)와 모바일 두 손가락 확대 추가했습니다.": "The opening tree's viewport and drag sensitivity now match the masters tree, and the masters tree gains zoom (100% baseline) and mobile pinch zoom.",
  "마스터 트리의 챔피언·랭킹·마스터 블록 디자인을 새로 다듬고 고급 서체로 교체했습니다. 가운데 칩에서 사방으로 전류가 흐르는 효과 추가했습니다.": "Redesigned the champion, ranking and master blocks in the masters tree with premium typefaces, and added an electric current effect flowing from the central chip in all four directions.",
  "탁월한 수 판정이 체크메이트가 걸린 상황에서 독이 든 희생을 통과시키던 문제를 수정했습니다.": "Fixed brilliant-move detection letting poisoned sacrifices through in positions involving checkmate.",
  "모바일에서 마스터 상세 카드가 잘려 보이던 문제를 수정했습니다.": "Fixed the master detail card being clipped on mobile.",
  "마스터 도감, 수 등급 보드 효과, 앱스토어 출시 준비, 탁월한 수 판정 보정했습니다.": "Masters dex, move-grade board effects, App Store prep, brilliant-move fix.",
  "마스터 도감, FIDE 상위 100위, 수 등급 효과, 앱스토어 준비 추가했습니다.": "Masters dex, FIDE top 100, move-grade effects, App Store prep",
  "마스터 도감, FIDE 상위 100위, 수 등급 효과, 앱스토어 준비": "Masters dex, FIDE top 100, move-grade effects, App Store prep",
  "계정 및 데이터 삭제 안내": "Account and data deletion",
  "1. 앱·웹에서 직접 삭제": "1. Delete it yourself in the app or on the web",
  "OpenChess에 로그인한 뒤 설정 탭에서 계정 센터 열기": "Log in to OpenChess and open the Account center from the Settings tab",
  "계정 센터 아래쪽의 \"계정 탈퇴\"를 누르고 아이디를 입력해 확인": "Tap \"Delete account\" at the bottom of the Account center and type your username to confirm",
  "2. 삭제되는 데이터": "2. Data that is deleted",
  "계정 정보(이메일, 로그인 수단 연결, 아이디, 닉네임, 회원 번호)와 프로필 사진·소개": "Account information (email, linked sign-in methods, username, nickname, member number) and your profile photo and bio",
  "학습 진도, 퍼즐 풀이 기록과 직접 만든 퍼즐, 대국·미니게임 기록과 레이팅": "Learning progress, puzzle solve history and puzzles you created, game and minigame records, and ratings",
  "친구 관계, 채팅 메시지, 알림, 신고·차단 내역": "Friend connections, chat messages, notifications, and report and block history",
  "진행 중이던 대국은 기권 처리되어 상대에게 승리로 기록된 뒤 삭제": "Games in progress are resigned, recorded as a win for your opponent, and then deleted",
