  "무승부가 많음": "Many draws",
  "승부를 가리는 편": "Tends to play for a result",
  "하이라이트": "Highlights",
  "최선: {0}": "Best: {0}",
  "승률 {0}%p 변동": "Win rate swing {0}%p",
  "OpenChess 하이라이트": "OpenChess highlights",
  "OpenChess 대국 하이라이트": "OpenChess game highlights",
  "하이라이트 카드로 공유": "Share as highlight card",
  "승률 흐름": "Win rate flow",
  "전체 화면": "Full screen",
  "전체 화면 닫기": "Exit full screen",
  "지우기": "Clear",
  "뒤집기": "Flip",
  "클립보드에서 붙여넣기": "Paste from clipboard",
  "PGN은 검증 후 그 수순 그대로 분석 탭에서 이어 둘 수 있음. FEN은 그 포지션(차례·캐슬링 권리·앙파상 포함)부터 이어 두는 FEN 모드로 전환됨.": "A PGN is checked and then loaded as-is so you can keep playing from it on the Analysis tab. A FEN switches to FEN mode, continuing from that position (turn, castling rights, and en passant included).",
  "구간 × 유형": "Phase × type",
  "그만하기": "Stop",
  "전체 {0}장, 익힌 카드 {1}장": "Total cards: {0}, Mastered: {1}",
  "나와 닮은 마스터": "Masters you play like",
  "{0}와(과) 기준별 비교": "Criterion-by-criterion comparison with {0}",
  "비슷한 기준 {0}/{1}": "Similar criteria {0}/{1}",
  "성장 분석": "Growth analysis",
  "성장 분석을 새로 만들고, 유산을 게시물로 바꿨습니다. 플레이 퀘스트가 생기고 티어 승급과 티어 여정, 도감도 새 디자인이 됐습니다.": "Growth analysis was rebuilt and legacies became posts. Play quests arrived, and tier promotion, the tier journey and the collection got new designs.",
  "성장 분석이 최근 대국 5판을 알아서 분석합니다.": "Growth analysis now analyzes your latest 5 games by itself.",
  "성장 분석을 새로 만들었습니다. 최근 대국 5판을 컴퓨터가 알아서 리뷰해 성장 요약, 약점 진단, 지금 고칠 한 가지, 실수 기록, 마스터 스타일로 보여 줍니다.": "Growth analysis is new. The computer reviews your latest 5 games by itself and shows a summary, weakness diagnosis, the one thing to fix now, a mistake log and your master style.",
  "실수 기록은 한 수씩 블록으로 보여 줍니다. 승률이 얼마나 떨어졌는지, 왜 떨어졌는지, 대신 둘 수 있었던 수는 무엇인지 알려 줍니다.": "The mistake log shows each move as a block: how much win probability dropped, why, and which moves you could have played instead.",
  "유산이 게시물이 됐습니다. 최대 200개까지 쌓이고, 좋아요와 리포스트, 친구에게 보내기를 할 수 있으며 한 줄 가로 스크롤로 넘겨 봅니다.": "Legacies are now posts. You can keep up to 200, like and repost them, send them to friends, and browse them in one swipeable row.",
  "유산에 공유 링크가 생겼습니다. openchess.kr/legacy/고유번호 주소로 로그인 없이 볼 수 있고, 남의 유산도 채팅으로 보낼 수 있습니다.": "Legacies now have share links. Open openchess.kr/legacy/ID without logging in, and you can also send other players' legacies in chat.",
  "유산 재생기를 처음부터 다시 만들었습니다. 금색 액자가 그려지며 열리고, 유산 수 직전에 나머지 기물이 어두워지며 표적이 잡힌 뒤 도착하면 등급 배지가 튀어 오릅니다.": "The legacy player was rebuilt from scratch. A gold frame draws itself, the other pieces dim and a target locks just before the key move, and a rating badge pops when it lands.",
  "플레이 탭에 플레이 퀘스트가 생겼습니다. 일반 대국과 미니게임에서 조건을 달성하면 클리어되고, 한국 시간 자정에 새로 시작합니다.": "The Play tab has Play quests. You clear them by meeting conditions in standard games and minigames, and they reset at midnight Korea time.",
  "프로필 카드를 띄우던 곳은 모두 내 /user 페이지로 이어지고, 그 페이지의 설정(세로 점 세 개) 버튼에서 프로필을 편집합니다.": "Every place that opened the profile card now goes to your /user page, where you edit your profile from the settings (three-dot) button.",
  "데스크톱의 검색, 프로필, 친구, 채팅 창에 확대 버튼을 넣었습니다. 누르면 화면 거의 전체 크기로 커집니다.": "Desktop search, profile, friends and chat windows have an expand button that grows them to nearly full screen.",
  "티어 승급 연출을 처음부터 다시 만들었습니다. 원근 격자 무대에서 링이 차오르고 부서진 뒤, 새 기물이 내리꽂히며 이름이 글자마다 켜집니다.": "The tier promotion scene was rebuilt from scratch. Rings charge and shatter on a perspective grid stage, the new piece slams in, and the name lights up letter by letter.",
  "티어 여정을 티어마다 한 장씩 쌓이는 연대기로 바꿨습니다. 티어마다 직접 그린 고유한 배경과 구간 사다리가 있고, 화면 크기에 맞춰 배치가 바뀝니다.": "The tier journey is now a chronicle with one chapter per tier. Each tier has its own hand-drawn background and a division ladder, and the layout adapts to the screen size.",
  "도감 첫 화면의 카드 네 장을 테마마다 색과 무늬가 다른 포스터형으로 다시 디자인했습니다.": "The four cards on the collection home screen were redesigned as posters, each with its own colour and pattern.",
  "집중 분석 모드에 사이트 톤으로 직접 만든 스크롤바를 넣었습니다.": "Focus analysis mode has a custom scrollbar in the site's own style.",
  "학습 탭을 다듬었습니다. 최근 대국 박스는 시간 규정을 플레이 탭과 같은 표기로 보여 주고 흑백 필터가 생겼으며, 칭호는 이름 아래 한 줄로 따로 표시합니다.": "The Learn tab was polished. Recent game boxes show time controls the same way as the Play tab and have a colour filter, and the title now sits on its own line below the name.",
  "빠른 리뷰 진입 연출을 다듬었습니다. 게이지가 찰 때마다 아래 이름이 글리치와 함께 바뀌고, 글자마다 비슷한 시간 동안 보입니다.": "The quick review intro was refined. As each gauge fills, the name below changes with a glitch, and every letter is shown for a similar amount of time.",
  "성장 요약 타일의 폰트와 정렬을 정리했습니다. 숫자가 칸 밖으로 넘쳐 옆 칸과 겹치던 문제를 없앴습니다.": "Fonts and alignment of the growth summary tiles were cleaned up, and numbers no longer overflow into the next tile.",
  "모바일에서 빠른 리뷰를 쓰면 정확도가 나오는 화면으로 먼저 들어갑니다.": "On mobile, quick review opens on the accuracy screen first.",
  "모바일에서 플레이 탭도 게임과 퀘스트를 학습 탭과 같은 두 페이지 스와이프로 보여 줍니다. 탭 상단의 제목은 모두 없앴습니다.": "On mobile, the Play tab shows the game and quests as the same two-page swipe as the Learn tab. The titles at the top of tabs are gone.",
  "/about 소개 페이지에서 다른 서비스 이름을 모두 지웠고, 모든 버전 설명과 업데이트 소식, 개발자 기록을 존댓말 문장으로 통일했습니다.": "All other service names were removed from the /about page, and every version description, the update news and the developer log now use polite sentences.",
  "집중 분석에서 마스터 통계에서 해설로 버튼을 눌러도 반쯤 넘어가다 멈추던 문제를 고쳤습니다.": "Fixed focus analysis stopping halfway when you pressed the Commentary button from master stats.",
  "데스크톱의 검색, 프로필, 친구, 채팅 창 안에서 마우스 휠로 가로 스크롤이 안 되던 문제를 고쳤습니다.": "Fixed horizontal rows inside desktop search, profile, friends and chat windows not scrolling with the mouse wheel.",
  "안드로이드 기기의 빠른 리뷰 화면에서 게이지와 이름이 OPEN 글자 위에 겹치던 문제를 고쳤습니다.": "Fixed the gauge and names overlapping the OPEN letters on the quick review screen of some Android devices.",
