  "횟수": "Count",
  "학습 탭은 내 성장을 모아 둔 곳입니다.": "Your growth, all in one place.",
  "내 대국을 5판 이상 리뷰하면 열립니다. 모자랄 때는 게이지 바로 남은 판 수를 알려 줍니다.": "Opens once you review 5 or more of your games. Until then, a gauge bar shows how many are left.",
  "대국마다 오프닝, 전적, 탁월한 수와 유일한 수의 개수가 보입니다. 연두색 버튼으로 바로 리뷰할 수 있습니다.": "Each game shows its opening, record, and the number of Brilliant and Only move counts. The green button reviews it right away.",
  "레슨은 갈래를 따라 순서대로 열리고, 오프닝 원칙부터 시작합니다.": "Lessons unlock in order along the branches, starting with opening principles.",
  "리뷰한 대국이 {0}판 이상이면 성장 분석이 열림": "Growth analysis unlocks after you review {0} or more games",
  "{0}판 더 리뷰하면 열림": "Review {0} more to unlock",
  "최근 대국의 연두색 리뷰 버튼으로 내 대국을 리뷰하면 한 판씩 쌓임": "Reviewing your games with the green Review button in Recent games adds them one by one",
  "분석한 실수": "Mistakes analyzed",
  "백 1.e4 선택": "Plays 1.e4 as White",
