  "오프닝 선택": "Opening choice",
  "중반 성향": "Middlegame tendencies",
  "대국 흐름": "Game flow",
  "약 {0}수": "~{0} moves",
  "거의 같음": "Almost the same",
  "비슷함": "Similar",
  "다름": "Different",
  "많이 다름": "Very different",
  "비교 불가": "Not comparable",
  "차이": "Gap",
  "판정 기준 — 비율 기준(오프닝 선택·캐슬링·퀸 교환·무승부)은 %p 차이로 {0}%p 이하 거의 같음, {1}%p 이하 비슷함, {2}%p 이하 다름, 그 이상 많이 다름. 빈도·길이 기준은 두 값의 배수로 판정하며 체크·기물 잡기는 {3}배, 대국 길이는 {4}배 이하면 거의 같음. 실력 비교가 아님": "How levels are set: for share criteria (opening choice, castling, queen trades, draws) the gap in percentage points decides — up to {0}%p almost the same, up to {1}%p similar, up to {2}%p different, more than that very different. Frequency and length criteria use the ratio of the two values: up to {3}× for checks and piece captures and up to {4}× for game length counts as almost the same. This is not a strength comparison",
  "마스터 이름으로 검색": "Search masters by name",
  "와(과) 기준별 비교": "Compared with you, by criterion",
  "일치도 {0}%": "Match {0}%",
  "학습 탭에 '성장 분석' 추가했습니다. 내 실수를 모아 보여 주는 약점 지도, 틀린 포지션을 간격을 두고 다시 푸는 복습 카드, 나와 닮은 마스터를 13가지 기준으로 비교하는 마스터 스타일 추가했습니다. 마스터 이름을 검색해 원하는 마스터와도 비교 추가했습니다.": "Added “Growth analysis” to the Learn tab: a weakness map of your mistakes, review cards that bring back positions you got wrong at spaced intervals, and Master style, which compares you with masters across 13 criteria. Search any master by name to compare with them too.",
  "게임 리뷰 공유에 '하이라이트 카드' 추가했습니다. 한 판에서 가장 극적인 수 3개를 보드 그림과 승률 흐름으로 한 장에 담습니다.": "Added a “Highlights card” to review sharing: the 3 most dramatic moves of a game on one image with board pictures and the win-rate flow.",
  "도감 오프닝 트리·마스터 트리와 퍼즐 모식도에 전체 화면 보기 추가했습니다. 왼쪽 위 버튼으로 켜고 끔 추가했습니다.": "Added full-screen view to the Openings tree, the Masters tree, and the puzzle schematic. Toggle it with the button at the top left.",
  "스마트폰 뒤로가기 지원합니다. 화면을 한 단계씩 닫고 홈에서는 한 번 더 누르면 종료했습니다. 앱에서 외부 링크는 시스템 브라우저·메일 앱·외부 사이트 앱으로 열기 추가했습니다.": "Added smartphone back button support: it closes screens one step at a time, and on Home a second press exits. In the app, external links open in the system browser, the mail app, or the external site app.",
  "계정 및 데이터 삭제 안내 페이지(/account-deletion) 추가했습니다. 탈퇴하면 진행 중이던 대국은 기권 처리되고 내가 만든 퍼즐도 함께 삭제했습니다.": "Added an account and data deletion page (/account-deletion). When you delete your account, games in progress are resigned and puzzles you made are deleted too.",
  "분석 탭 보드 위 버튼을 복사, 편집, 리뷰 순서로 정리하고 편집 버튼에 글자 추가했습니다. FEN/PGN 붙여넣기는 보드 편집 화면의 '불러오기'로 통합했습니다.": "Reordered the buttons above the Analysis board to Copy, Edit, Review and added text to the Edit button. FEN/PGN pasting moved into “Load” on the board edit screen.",
  "보드 편집 화면을 새로 디자인했습니다. 보드 중심 배치, 도구·기물·차례·불러오기·FEN 카드 추가했습니다.": "Redesigned the board edit screen: board-centered layout with cards for tools, pieces, turn, loading, and FEN.",
  "도감 마스터 이름을 모든 언어에서 영어로 통일했습니다.": "Master names in the Dex are now shown in English in every language.",
  "체크메이트 뒤 상대가 나가 끝나지 않은 대국이 새 매칭을 막던 문제를 수정했습니다. 결과 확정 요청이 실패하면 다시 시도 추가했습니다.": "Fixed finished games that never ended after checkmate because the opponent left blocking new matches. Result confirmation now retries if it fails.",
  "탈퇴한 계정이 만든 퍼즐에 작성자 아이디가 남던 문제를 수정했습니다.": "Fixed the creator name staying on puzzles made by a deleted account.",
  "좁은 화면에서 프로필 카드 위쪽 아이디가 버튼과 겹치던 문제를 수정했습니다. 통계 토글은 왼쪽, 프로필 편집은 오른쪽 정렬했습니다.": "Fixed the username at the top of the profile card overlapping the buttons on narrow screens. The stats toggle is aligned left and Edit profile right.",
  "성장 분석, 하이라이트 카드, 모식도 전체 화면, 스마트폰 뒤로가기, 계정 삭제 정리했습니다.": "Growth analysis, Highlights card, Full-screen schematics, smartphone back button, Account deletion cleanup.",
  "성장 분석, 하이라이트 카드, 모식도 전체 화면, 계정 삭제 안내합니다.": "Growth analysis, Highlights card, Full-screen schematics, Account deletion guide",
