  "예방 수이며, 상대 {1:은/는} {0}에 왔다면 {2:을/를} 위협받았을 것입니다.": "Prophylactic move. An opponent {1} entering {0} would threaten the {2}",
  "{0}의 컨트롤을 늘린 예방 수이며, 상대 {1:이/가} 여기 와서 {2:을/를} 위협하는 걸 간접적으로 막았습니다.": "Prophylactic move, stronger control of {0} indirectly blocks the threat to the {2} after an opponent {1} enters",
