  "킹의 안전을 도모하는 것은 대부분의 상황에서 좋은 선택입니다.": "Securing the king is a good choice in most situations",
  "캐슬링으로 킹을 안전한 곳에 두는 건 언제나 우선순위가 높은 선택입니다.": "Castling to put the king in safety is a high-priority choice",
  "킹을 미리 안전지대로 옮겨두는 좋은 선택입니다.": "Moving the king to safety early is a good choice",
