  "이 길이의 오프닝이 도감에 없음": "No openings of this length in the Opening Dex",
  "이 포지션의 최선의 수는?": "What's the best move in this position?",
  "이미 끝난 포지션은 퀴즈로 낼 수 없음": "A finished position can't be used for a quiz",
  "읽을 수 없는 룰렛": "Unreadable roulette",
