  "{0:은/는} 움직일 칸이 {1}칸밖에 없어 답답한 자리입니다.": "The {0} has just {1} squares to move to, a cramped spot.",
  "측면의 {0}열 폰을 앞으로 밀어 {1} 공간을 넓힙니다.": "Pushing the wing Pawn, {0}-file,  forward gains space on the {1}.",
  "{1}에서 {0}폰을 전진시켜 공간을 확보했습니다.": "On the {1}, the {0}-file Pawn advanced to gain space.",
