  "장의 퀘스트를 모두 클리어하면 더 어려운 다음 장이 열림. 일반 대국은 10수(양쪽 합 20수) 이상 두고 끝내야 인정됨": "Clear every quest in a chapter to unlock the harder next chapter. Standard games count only if they last 10 moves (20 plies) or more",
